183: // Render produces a host-specific instruction payload for an IR.
184: func Render(ir *core.IR, options core.RenderOptions) core.RenderResult {
185: 	file := "<render>"
186: 	if ir != nil && len(ir.Provenance) > 0 {
187: 		file = ir.Provenance[0].File
188: 	}
189: 	r := &renderer{options: options, diagnostics: []core.Diagnostic{}, file: file}
190: 
191: 	if ir == nil {
192: 		r.report("RENDER_NIL_IR", "Cannot render a nil IR")
193: 		return core.RenderResult{Text: "", Diagnostics: r.diagnostics}
194: 	}
195: 	switch options.Host {
196: 	case core.HostCursor, core.HostOpenCode, core.HostAgentsMD, core.HostMarkdown:
197: 	default:
198: 		r.report("RENDER_UNKNOWN_HOST", fmt.Sprintf("Unknown host format %q, using markdown", options.Host))
199: 		r.options.Host = core.HostMarkdown
200: 	}
201: 	switch options.Mode {
202: 	case core.ModeInline, core.ModeFile, core.ModeCompact, core.ModeVerbose:
203: 	default:
204: 		r.report("RENDER_UNKNOWN_MODE", fmt.Sprintf("Unknown injection mode %q, using INLINE", options.Mode))
205: 		r.options.Mode = core.ModeInline
206: 	}
207: 
208: 	includeDelimiters := true
209: 	if options.IncludeDelimiters != nil {
210: 		includeDelimiters = *options.IncludeDelimiters
211: 	}
212: 
213: 	var out strings.Builder
214: 	out.WriteString(r.hostHeader(ir))
215: 	out.WriteString(interpretationInstruction)
216: 	out.WriteString("\n\n")
217: 	if includeDelimiters {
218: 		out.WriteString(beginMarker)
219: 		out.WriteString("\n\n")
220: 	}
221: 	if r.options.Mode == core.ModeFile {
222: 		out.WriteString("<!-- Loaded through the host-native file discovery mechanism. -->\n\n")
223: 	}
224: 	out.WriteString(r.renderRules(ir))
225: 	if includeDelimiters {
226: 		out.WriteString("\n")
227: 		out.WriteString(endMarker)
228: 	}
229: 	out.WriteString("\n")
230: 
231: 	return core.RenderResult{Text: out.String(), Diagnostics: r.diagnostics}
232: }
