188: 	}
189: 	r := &renderer{options: options, diagnostics: []core.Diagnostic{}, file: file}
190: 
191: 	if ir == nil {
192: 		r.report("RENDER_NIL_IR", "Cannot render a nil IR")
193: 		return core.RenderResult{Text: "", Diagnostics: r.diagnostics}
194: 	}
195: 	switch options.Host {
196: 	case core.HostCursor, core.HostOpenCode, core.HostAgentsMD, core.HostMarkdown:
197: 	default:
198: 		r.report("RENDER_UNKNOWN_HOST", fmt.Sprintf("Unknown host format %q, using markdown", options.Host))
199: 		r.options.Host = core.HostMarkdown
200: 	}
201: 	switch options.Mode {
202: 	case core.ModeInline, core.ModeFile, core.ModeCompact, core.ModeVerbose:
203: 	default:
204: 		r.report("RENDER_UNKNOWN_MODE", fmt.Sprintf("Unknown injection mode %q, using INLINE", options.Mode))
205: 		r.options.Mode = core.ModeInline
206: 	}
